const financeFields={company:'Empresa solicitante',cnpj:'CNPJ da solicitante',representative:'Nome do representante',contact:'Contato do representante',number:'Número do documento',date:'Data',issuer:'Empresa prestadora',issuerCnpj:'CNPJ da prestadora',issuerContact:'Contato da prestadora',service:'Serviços executados',equipment:'Equipamentos / referências',amount:'Valor total',notes:'Observações',responsible:'Responsável pelo preenchimento',terms:'Condições / rodapé'};
function financeDB(){const initialize=!db.finance;db.finance??={templates:[],documents:[]};if(initialize){db.finance.templates=[{id:'default-os',name:'Ordem de serviço padrão',kind:'OS',mode:'standard',issuer:'',issuerCnpj:'',issuerContact:'',terms:'Serviços executados conforme descrição acima.'},{id:'default-nf',name:'Rascunho de nota padrão',kind:'NF',mode:'standard',issuer:'',issuerCnpj:'',issuerContact:'',terms:'Rascunho para conferência. Sem validade fiscal.'}];save()}financeMigrateModels(db.finance);return db.finance}
function financeStorage(){return new Promise((resolve,reject)=>{const req=indexedDB.open('bancada-documents',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(Error('Não foi possível acessar o armazenamento dos PDFs.'))})}
async function financeFile(key,value){const storage=await financeStorage();try{return await new Promise((resolve,reject)=>{const tx=storage.transaction('files',value===undefined?'readonly':'readwrite'),store=tx.objectStore('files');let result;const req=value===undefined?store.get(key):store.put(value,key);req.onsuccess=()=>result=req.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(Error('Não foi possível salvar o PDF. Verifique o espaço disponível no navegador.'));tx.onabort=()=>reject(Error('Armazenamento do PDF interrompido.'))})}finally{storage.close()}}
function financeError(e){toast(e.message||'Não foi possível concluir a operação.')}
function financeDownload(bytes,name){const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function financeInput(name,title,value='',options=''){return `<label>${title}<input name="${name}" value="${esc(value)}" ${options}></label>`}
function financeFilename(d){return `${d.kind==='OS'?'OS':'RASCUNHO'}-${d.number.replace(/[^a-zA-Z0-9_-]/g,'_')}.pdf`}
async function financeTemplate(id,kind='OS'){
 const existing=financeDB().templates.find(t=>t.id===id),t=existing||{name:'',kind,terms:''},provider=financeProvider();
 showModal(existing?'Editar modelo':'Cadastrar modelo',financeInput('name','Nome do modelo',t.name,'required maxlength="80"')+'<label>Tipo de documento<select name="kind"><option value="OS" '+(t.kind==='OS'?'selected':'')+'>Ordem de serviço</option><option value="NF" '+(t.kind==='NF'?'selected':'')+'>Rascunho de nota fiscal</option></select></label><p class="note">Prestadora padrão: <strong>'+esc(provider.name||'Ainda não configurada')+'</strong><br>O cabeçalho, o CNPJ, o logotipo e os contatos são herdados do cadastro único da prestadora.</p><label>Condições / textos padrão<textarea name="terms" maxlength="1500">'+esc(t.terms)+'</textarea></label>',values=>{try{values.name=values.name.trim();if(!values.name)throw Error('Informe o nome do modelo.');if(existing)Object.assign(existing,values);else financeDB().templates.push({...values,id:crypto.randomUUID(),mode:'standard'});save();$('#modal').close();controladoria();toast('Modelo salvo.')}catch(e){$('#formerror').textContent=e.message}})
}
function validCnpj(value){const s=value.replace(/\D/g,'');if(s.length!==14||/^(\d)\1+$/.test(s))return false;const calc=n=>{let sum=0,weight=n-7;for(let i=0;i<n;i++){sum+=Number(s[i])*weight--;if(weight<2)weight=9}const r=sum%11;return r<2?0:11-r};return calc(12)===Number(s[12])&&calc(13)===Number(s[13])}
function financeRemoveTemplate(id){const f=financeDB(),i=f.templates.findIndex(t=>t.id===id);if(i<0)throw Error('Modelo não encontrado.');const [t]=f.templates.splice(i,1);f.deletedTemplates??=[];f.deletedTemplates.push(t);for(const kind of Object.keys(f.defaultTemplates||{}))if(f.defaultTemplates[kind]===id)delete f.defaultTemplates[kind];save();return t}
function financeDeleteTemplate(id){const t=financeDB().templates.find(t=>t.id===id);if(!t)return;showModal('Excluir modelo',`<p style="font-size:14px;line-height:1.7">Excluir o modelo <strong>${esc(t.name)}</strong> da lista de modelos disponíveis?</p><p class="note">Os PDFs já gerados serão mantidos. Você poderá restaurar este modelo depois.</p>`,()=>{try{financeRemoveTemplate(id);$('#modal').close();controladoria();toast('Modelo excluído. Os PDFs foram preservados.')}catch(e){$('#formerror').textContent=e.message}});$('#form .primary').textContent='Excluir modelo';$('#form .primary').classList.add('danger')}
function financeRestoreTemplate(){const f=financeDB(),t=f.deletedTemplates?.pop();if(!t)return;if(!f.templates.some(v=>v.id===t.id))f.templates.push(t);save();controladoria();toast('Modelo restaurado.')}
